values
  ('gcc', 'GCC Diversified Hub', '🌐', ARRAY['Diversification', 'Logistics Hub', 'Moderate ICV'], 'High-income trade-hub economy diversifying away from hydrocarbons — balanced evaluation scoring, strong logistics-corridor emphasis in Export, moderate local-content pressure.', ARRAY['procurement'::pillar_id, 'b2b'::pillar_id, 'import'::pillar_id, 'export'::pillar_id, 'investment'::pillar_id, 'sustainability'::pillar_id], '{"procurement": {"evalWeights": {"technical": 30, "commercial": 30, "icv": 15, "esg": 10, "compliance": 15}}, "b2b": {"matchWeights": {"industry": 25, "product": 20, "location": 20, "certification": 15, "pastPerformance": 10, "icv": 10}}, "import": {"dutyBands": {"general": 5, "foodstuffs": 0, "industrialInputs": 0, "luxury": 100}}, "export": {"readinessWeights": {"productReadiness": 15, "certifications": 15, "quality": 15, "pricing": 15, "logistics": 25, "financial": 10, "marketFit": 5}, "incentives": ["Re-Export Duty Exemption", "Logistics Corridor Subsidy", "Free Zone Export Processing"]}, "investment": {"investorMatchWeights": {"sectorFit": 25, "riskAppetite": 15, "esgAlignment": 20, "icvPotential": 15, "returnProfile": 25}, "icThreshold": 15, "incentives": ["100% Foreign Ownership", "Multi-Modal Logistics Access", "Long-Term Land Lease (50yr)"]}, "sustainability": {"greenProcurement": {"esgThreshold": 15}}}'::jsonb),
